"""Record implementation/campaign/action/flow hierarchy without changing splits."""
import csv,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
WORK=ROOT.parent.parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def main():
    rows=[];sources=[]
    base=WORK/'拟合来源与划分落实_20261119/ait_new_runs'
    validation=json.loads((base/'network_delivery_validation.json').read_text(encoding='utf-8'))
    sources.append({'path':str(base/'network_delivery_validation.json'),'sha256':sha(base/'network_delivery_validation.json')})
    for run,role in [('santos','F'),('fox','V')]:
        summary=next(x for x in validation['summary_by_run'] if x['run']==run)
        events=[json.loads(x) for x in (base/'network_mapping'/run/'events.jsonl').read_text(encoding='utf-8').splitlines()]
        attack=[x for x in events if x['kind'] in ('webshell_command','attack_download','reverse_shell_channel')]
        rows.append({'source':'AIT-LDS','implementation_family_id':'ait:wpdiscuz_webshell_download_reverse_recipe','campaign_id':f'ait:{run}:wpdiscuz_complete_chain','current_role':role,'new_fit_role_assigned':False,'implementation_relation':'same recipe across santos/fox/russell; different run is not different implementation','attack_action_events':len(attack),'action_counts':{k:sum(e['kind']==k for e in attack) for k in ('webshell_command','attack_download','reverse_shell_channel')},'positive_connection_counts':summary['positive_connections_by_event_kind'],'positive_connections':summary['connection_labels']['1'],'normal_connections_conditional_B':summary['connection_labels']['0'],'all_target_actions_have_network_candidates':True,'whole_capture_available':True,'precise_framework_or_recipe_known':True,'new_implementation_increment':0,'event_ids':[e['event_id'] for e in attack],'source_path':str(base/'network_mapping'/run/'events.jsonl')})
    optc=WORK/'独立来源与算法主线_20261118/evidence/optc'
    for name in ('optc_control_channel_slice.json','optc_event_slice.json'):
        sources.append({'path':str(optc/name),'sha256':sha(optc/name)})
    control=json.loads((optc/'optc_control_channel_slice.json').read_text(encoding='utf-8'))
    rows.append({'source':'OpTC','implementation_family_id':'optc:empire_powershell_custom','campaign_id':'optc:empire_custom:20190924_continues_20190925','current_role':'externaldev','new_fit_role_assigned':False,'implementation_relation':'independent source and Empire implementation; retained opened external development only','attack_action_events':None,'action_counts':{'known_control_channel_connections':24,'observed_download_occurrences_same_file_same_chain':2},'positive_connections':26,'control_author_ecar_conn_exact_matches':control['counts']['joined_label_known_control_channel'],'normal_scope':'separately assembled declared normal business subset; six news.com PE downloads remain unknown','whole_capture_available':'selected complete rotations only','precise_framework_or_recipe_known':True,'new_implementation_increment':0,'source_path':str(optc/'optc_control_channel_slice.json')})
    assembled=json.loads((ROOT/'network_mapping/assembly_receipt.json').read_text(encoding='utf-8'))
    rows.append({'source':'Unraveled','implementation_family_id':'unraveled:drive_by_implant_tls:framework_unresolved','campaign_id':'unraveled:apt_2021_single_campaign','current_role':'opened_source_qualification_development','new_fit_role_assigned':False,'implementation_relation':'author APT drive-by campaign and TLSv1.3 C2, distinct from wpDiscuz webshell; Covenant/Metasploit/Sliver cannot be assigned per flow','attack_action_events':1,'action_counts':{'known_C2_channel_activity_episode':1,'individual_commands_proven':0,'attack_download_actions_proven':0},'positive_connections':5,'positive_connection_label_basis':'B: author per-flow Exfiltration over C2 channel + exact original PCAP/Zeek linkage','normal_connections_conditional_B':16,'candidate_connections':25,'incomplete_candidates_retained':4,'all_slice_background_connections':381,'whole_capture_available':False,'whole_campaign_available':False,'precise_framework_or_recipe_known':False,'new_implementation_increment':1,'new_independent_campaign_increment':1,'event_ids':['unraveled:20210621:apt:c2_channel_episode'],'source_path':str(ROOT/'network_mapping/events.jsonl'),'current_fit_validation_admission':'not ready: partial campaign, no proven attack download, no F/V assignment; framework name is not a C2-label prerequisite'})
    rejected={'source':'IEU-C2D / C2Detector public data','current_role':'not_admitted','public_artifact':'C2.zip 1860186 bytes; README explicitly describes released interaction-state transitions','raw_network_mapping_available':False,'normal_business_ground_truth_available':False,'reason':'public representation does not expose packets/actions/normal business required by this input contract; original experiment traffic volume is not evidence of publicly released PCAP','readme_path':str(ROOT/'source/ieu_c2d/README.md'),'directory_path':str(ROOT/'source/ieu_c2d/directory.json')}
    table={'created_date':'2026-11-19','no_training_or_model_scoring':True,'hierarchy_rule':'implementation family != independent run/campaign != action != flow; repeated flows and two downloads of one file do not create independent campaigns','coverage':rows,'current_fit_validation_implementation_families':1,'already_opened_additional_control_families':['OpTC Empire','Unraveled TLS implant C2 (framework unknown)'],'new_ready_fit_validation_implementation_families':0,'new_mapped_control_family_increment':1,'new_proven_attack_download_implementation_increment':0,'reserved_untouched':['AIT harrison','OpTC Meterpreter'],'rejected_source':rejected,'source_receipts':sources,'unraveled_assembly_receipt':assembled}
    full_path=ROOT/'full_capture/assembly_receipt.json'
    if full_path.exists():
        full=json.loads(full_path.read_text(encoding='utf-8'))
        unraveled=next(r for r in rows if r['source']=='Unraveled')
        unraveled.update({'current_role':'opened_source_development','positive_connections':full['target_host_target_kind_counts']['c2'],'normal_connections_conditional_B':full['target_host_target_kind_counts']['normal'],'other_attack_connections':full['target_host_target_kind_counts']['other_attack'],'unknown_target_host_connections':full['target_host_target_kind_counts']['unknown'],'all_capture_background_connections':full['all_connections'],'whole_capture_available':True,'source_final_record_incomplete':True,'whole_campaign_available':False,'new_control_supervision_material_ready':True,'current_fit_validation_admission':'control supervision ready; role assigned by parent split manifest; no new attack download evidence','source_path':str(ROOT/'full_capture/events.jsonl'),'author_rows_matched':full['target_host_author_rows'],'all_source_author_rows_packet_verified':full['all_author_valid_rows'],'previous_slice_counts_superseded':True})
        unraveled['event_ids']=[e['event_id'] for e in map(json.loads,(ROOT/'full_capture/events.jsonl').read_text(encoding='utf-8').splitlines()) if e['semantic_kind']=='c2_channel']
        for old in ('candidate_connections','incomplete_candidates_retained','all_slice_background_connections'):unraveled.pop(old,None)
        table.update({'unraveled_assembly_receipt':full,'new_ready_fit_validation_implementation_families':None,'new_ready_control_supervision_families':1,'new_ready_independent_validation_families':0,'role_note':'Existing AIT F/V family count is before incorporating the new source. New Unraveled control supervision is ready; the parent owns F/V assignment.','source_version':'full_capture supersedes historical two slices'})
    dump(ROOT/'coverage_catalog.json',table)
    columns=('source','implementation_family_id','campaign_id','current_role','attack_action_events','positive_connections','whole_capture_available','precise_framework_or_recipe_known')
    with (ROOT/'coverage_table.csv').open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.DictWriter(f,fieldnames=columns);w.writeheader();w.writerows({k:r.get(k) for k in columns} for r in rows)
    for name,url in [('README.md','https://raw.githubusercontent.com/AmyDylen/IEU-C2D/main/README.md'),('directory.json','https://github.com/AmyDylen/IEU-C2D/tree/main')]:
        p=ROOT/'source/ieu_c2d'/name
        dump(ROOT/'receipts'/('ieu_c2d__'+name+'.json'),{'source_url':url,'retrieval':'connected GitHub fetch tool','local_path':str(p),'bytes':p.stat().st_size,'sha256':sha(p)})
    paths=[ROOT/'coverage_catalog.json',ROOT/'coverage_table.csv',ROOT/'full_author_day_summary.json',ROOT/'README.md',ROOT/'full_capture/README.md',*ROOT.glob('*.py'),*ROOT.glob('network_mapping/*.json'),*ROOT.glob('network_mapping/*.jsonl'),*ROOT.glob('source/unraveled/pcap_slices/*/receipt.json'),*ROOT.glob('full_capture/*receipt.json'),*ROOT.glob('source/unraveled/full_capture/*receipt.json'),ROOT/'source/unraveled/full_capture/tail_record_evidence.json']
    dump(ROOT/'delivery_receipt.json',{'no_training_or_model_scoring':True,'files':[{'path':str(p),'bytes':p.stat().st_size,'sha256':sha(p)} for p in paths if p.exists()]})
    print(json.dumps({'new_C2_family_mapped':1,'full_capture_ready':full_path.exists(),'unraveled_connections':full['all_connections'] if full_path.exists() else assembled['all_slice_connections'],'unraveled_label_counts':full['target_host_target_kind_counts'] if full_path.exists() else assembled['connection_labels']}))
if __name__=='__main__':main()
